8	// 本文件为行情缺口期间“重复提交同序号报价”补充回归保障：已经进入等待的
9	// 报价不能被后来的同序号数据覆盖——相同内容幂等返回 0，不同内容报内容冲突
10	// 并保留原先等待的数据；等待与冲突都不得提前改变订单状态、资金占用、持仓
11	// 金额或事件记录。缺口补齐后报价按序号逐条生效，最终必须保留最初收到的
12	// 等待报价；若正是该报价使账户总持仓金额超限，撤单记录必须锚定最初等待的
13	// 原始报价定位，不能使用曾被冲突拒绝的数据。
14	//
15	// 共用前置状态（pendingConflictSetup）：
16	// 初始现金 1000；A 合约持仓限额充足；seq1（时刻 10，价格 10）已生效。
17	// 一笔 6 股限价 10 的买单成交 2 股 @10 后：现金 980、持仓 2，买单剩余 4 股
18	// 占用现金 40；账户总持仓金额上限设为 100：持仓金额 20 + 买单占用 40 = 60。
19	// 日内亏损保护不开启，设置上限时不撤单。
20	func pendingConflictSetup(t *testing.T) (e *Engine, bid int64, recsBase int) {
21		t.Helper()
22		e, _ = NewEngine(1000)
23		mustSetMax(t, e, "A", 1000) // 合约持仓限额充足，撤单只能来自账户金额上限
24		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 10, Price: 10}, 1)
25		bid = mustBuy(t, e, "A", 6, 10)
26		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 10, Qty: 2}); err != nil {
27			t.Fatal(err)
28		}
29		if _, err := e.SetPositionAmountLimit(100); err != nil {
30			t.Fatal(err)
31		}
32	
33		if e.Cash() != 980 || e.ReservedCash() != 40 || e.AvailableCash() != 940 || e.Position("A") != 2 {
34			t.Fatalf("前置资金状态错误: cash=%d reserved=%d available=%d pos=%d",
35				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"))
36		}
37		am := e.PositionAmountStatus()
38		if !am.Enabled || am.Limit != 100 || am.Holding != 20 || am.BuyReserved != 40 || am.Total != 60 {
39			t.Fatalf("前置金额状态错误: %+v", am)
40		}
41		if o, _ := e.Order(bid); o.Status != StatusPartial || o.Filled != 2 || o.Remaining() != 4 {
42			t.Fatalf("前置订单应为部分成交、剩余 4 股: %+v", o)
43		}
44		return e, bid, len(e.Records())
45	}
46	
47	// assertWaitingInvariant 校验等待/冲突期间任何请求都不得改变业务状态与事件记录。
48	func assertWaitingInvariant(t *testing.T, e *Engine, bid int64, recsBase int) {
49		t.Helper()
50		q, ok := e.CurrentQuote("A")
51		if !ok || q != (Quote{Seq: 1, Moment: 10, Price: 10}) {
52			t.Fatalf("等待期间最新已生效报价必须停在 seq1（时刻10,价格10）: %+v ok=%v", q, ok)
53		}
54		if !e.HasGap("A") {
55			t.Fatal("等待期间缺口必须保持存在")
56		}
57		if o, _ := e.Order(bid); o.Status != StatusPartial || o.Filled != 2 || o.Remaining() != 4 {
58			t.Fatalf("等待/冲突不得提前改变订单状态: %+v", o)
59		}
60		if e.Cash() != 980 || e.ReservedCash() != 40 || e.AvailableCash() != 940 || e.Position("A") != 2 {
61			t.Fatalf("等待/冲突不得提前改变资金或持仓: cash=%d reserved=%d pos=%d",
62				e.Cash(), e.ReservedCash(), e.Position("A"))
63		}
64		am := e.PositionAmountStatus()
65		if am.Holding != 20 || am.BuyReserved != 40 || am.Total != 60 {
66			t.Fatalf("等待/冲突不得提前改变金额占用: %+v", am)
67		}
68		if recs := e.Records(); len(recs) != recsBase {
69			t.Fatalf("等待/冲突不得新增事件记录: 基础 %d 条，现有 %d 条", recsBase, len(recs))
70		}
71	}
72	
73	// TestPendingQuoteDuplicateConflictKeptAndUsedOnGapFill 覆盖完整场景：
74	// seq1@（时刻10,价格10）为最新有效报价时先收到 seq3@（时刻30,价格20）进入
75	// 等待；相同内容重放成功返回 0，仅改价格或仅改时刻的请求报内容冲突并返回 0，
76	// 冲突后再提交原内容仍按相同数据处理。随后补交 seq2@（时刻20,价格10），2 条
77	// 报价依次生效且最终保留最初收到的 seq3@（时刻30,价格20）；该报价使持仓
78	// 金额 40 + 买单占用 80 = 120 超过上限 100，撤销买单全部剩余 4 股并释放 40
79	// 现金占用。补齐后重放原 seq3 仍返回 0，不再产生撤销或记录。
80	func TestPendingQuoteDuplicateConflictKeptAndUsedOnGapFill(t *testing.T) {
81		e, bid, recsBase := pendingConflictSetup(t)
82	
83		// 跨号 seq3 先到：提交成功但 0 条生效，最新报价停在 seq1，缺口保持。
84		n, err := e.UpdateQuote("A", Quote{Seq: 3, Moment: 30, Price: 20})
85		if err != nil || n != 0 {
86			t.Fatalf("跨号 seq3 应成功并返回 0 条生效: n=%d err=%v", n, err)
87		}
88		assertWaitingInvariant(t, e, bid, recsBase)
89	
90		// 完全相同的 seq3 再次提交：成功返回 0，不替换、不新增记录。
91		if n, err := e.UpdateQuote("A", Quote{Seq: 3, Moment: 30, Price: 20}); err != nil || n != 0 {
92			t.Fatalf("相同内容的等待报价重放必须成功返回 0: n=%d err=%v", n, err)
93		}
94		assertWaitingInvariant(t, e, bid, recsBase)
95	
96		// 仅把价格改为 10：内容冲突，返回 0；原先等待的 (时刻30,价格20) 必须保留。
97		if n, err := e.UpdateQuote("A", Quote{Seq: 3, Moment: 30, Price: 10}); err == nil || n != 0 {
98			t.Fatalf("同序号不同价格必须报内容冲突并返回 0: n=%d err=%v", n, err)
99		} else if !strings.Contains(err.Error(), "内容冲突") || !strings.Contains(err.Error(), "等待中") {
100			t.Fatalf("冲突错误必须指明等待中的报价内容冲突: %v", err)
101		}
102		assertWaitingInvariant(t, e, bid, recsBase)
103	
104		// 仅把时刻改为 99：同样内容冲突、返回 0、保留原等待数据。
105		if n, err := e.UpdateQuote("A", Quote{Seq: 3, Moment: 99, Price: 20}); err == nil || n != 0 {
106			t.Fatalf("同序号不同时刻必须报内容冲突并返回 0: n=%d err=%v", n, err)
107		}
108		assertWaitingInvariant(t, e, bid, recsBase)
109	
110		// 冲突后再提交原内容：仍被视为相同数据（成功返回 0），冲突请求不是替换报价。
111		if n, err := e.UpdateQuote("A", Quote{Seq: 3, Moment: 30, Price: 20}); err != nil || n != 0 {
112			t.Fatalf("冲突后重放原内容必须仍按相同数据处理: n=%d err=%v", n, err)
113		}
114		assertWaitingInvariant(t, e, bid, recsBase)
115	
116		// 补交缺失的 seq2：seq2@（时刻20,价格10）与等待的 seq3@（时刻30,价格20）
117		// 依次生效，共 2 条；最终报价必须是最初收到的 seq3。
118		recsBefore := len(e.Records())
119		n, err = e.UpdateQuote("A", Quote{Seq: 2, Moment: 20, Price: 10})
120		if err != nil {
121			t.Fatalf("补齐缺口必须成功: %v", err)
122		}
123		if n != 2 {
124			t.Fatalf("应有 2 条报价依次生效（seq2、seq3），实际 %d", n)
125		}
126		q, ok := e.CurrentQuote("A")
127		if !ok || q != (Quote{Seq: 3, Moment: 30, Price: 20}) {
128			t.Fatalf("最终报价必须保留最初收到的 seq3（时刻30,价格20），不得被冲突数据替换: %+v ok=%v", q, ok)
129		}
130		if e.HasGap("A") {
131			t.Fatal("补齐后缺口必须消失")
132		}
133	
134		// seq3@20 生效后：持仓金额 2×20=40，买单剩余 4×max(限价10,报价20)=80，
135		// 合计 120 > 上限 100，撤销买单全部剩余量并释放 40 现金占用。
136		o, _ := e.Order(bid)
137		if o.Status != StatusCanceled || o.Filled != 2 || o.Remaining() != 0 {
138			t.Fatalf("超限买单应撤销全部剩余 4 股、保留已成交 2 股: %+v", o)
139		}
140		if !strings.Contains(o.Reason, "金额上限") || !strings.Contains(o.Reason, "超限") ||
141			!strings.Contains(o.Reason, "报价序号 3") || !strings.Contains(o.Reason, "时刻 30") ||
142			!strings.Contains(o.Reason, "价格 20") {
143			t.Fatalf("撤单原因必须说明金额超限并锚定最初等待的 seq3（时刻30,价格20）: %q", o.Reason)
144		}
145		if e.Cash() != 980 || e.ReservedCash() != 0 || e.AvailableCash() != 980 || e.Position("A") != 2 {
146			t.Fatalf("撤单只释放剩余量现金占用，现金余额与已入账 2 股持仓保留: cash=%d reserved=%d pos=%d",
147				e.Cash(), e.ReservedCash(), e.Position("A"))
148		}
149		am := e.PositionAmountStatus()
150		if !am.Enabled || am.Limit != 100 || am.Holding != 40 || am.BuyReserved != 0 || am.Total != 40 {
151			t.Fatalf("补齐撤单后金额状态应为持仓 40、买单占用 0: %+v", am)
152		}
153	
154		// 本批只新增一条撤销记录（seq2@10 下合计 60 不超限，不产生记录）。
155		recs := e.Records()
156		newRecs := recs[recsBefore:]
157		if len(newRecs) != 1 {
158			t.Fatalf("补齐本批应只新增一条撤单记录，实际 %d 条", len(newRecs))
159		}
160		cr := newRecs[0]
161		if cr.Kind != RecordCanceled || cr.OrderID != bid || cr.Side != Buy ||
162			cr.Filled != 2 || cr.Remaining != 4 || cr.Qty != 6 || cr.Limit != 10 {
163			t.Fatalf("唯一新增记录必须是该买单剩余 4 股的撤销记录: %+v", cr)
164		}
165		// 撤销前两类金额、合计与上限必须固化：40 + 80 = 120 > 100。
166		if !cr.AmtEnabled || cr.AmtLimit != 100 || cr.AmtHolding != 40 ||
167			cr.AmtBuyReserved != 80 || cr.AmtTotal != 120 {
168			t.Fatalf("撤单记录应保存撤销前金额 40/80、合计 120 与上限 100: %+v", cr)
169		}
170		// 报价定位必须是最初收到并等待的 seq3@（时刻30,价格20），
171		// 不能使用曾被冲突拒绝的 (时刻30,价格10) 或 (时刻99,价格20)。
172		if !cr.QuoteValid || cr.QuoteSeq != 3 || cr.QuoteMoment != 30 || cr.QuotePrice != 20 {
173			t.Fatalf("撤单记录报价快照应锚定最初等待的 seq3（时刻30,价格20）: %+v", cr)
174		}
175		if len(cr.AmtQuoteRefs) != 1 ||
176			cr.AmtQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 3, Moment: 30, Price: 20}) {
177			t.Fatalf("撤单金额报价定位必须锚定最初等待的 seq3: %+v", cr.AmtQuoteRefs)
178		}
179		if cr.RiskDay != 0 {
180			t.Fatalf("未开启日内亏损保护时撤单记录不得携带风险快照: %+v", cr)
181		}
182		for _, r := range recs[recsBase:] {
183			if r.Kind == RecordRejected {
184				t.Fatalf("全过程不得留下拒绝记录（含等待期间的内容冲突）: %+v", r)
185			}
186		}
187	
188		// 补齐后再次提交原 seq3：已是已生效报价，相同内容返回 0，
189		// 不再产生撤销或任何记录，资金、持仓与订单保持。
190		if n, err := e.UpdateQuote("A", Quote{Seq: 3, Moment: 30, Price: 20}); err != nil || n != 0 {
191			t.Fatalf("补齐后重放原 seq3 必须成功返回 0: n=%d err=%v", n, err)
192		}
193		if len(e.Records()) != len(recs) {
194			t.Fatal("补齐后重放 seq3 不得新增任何记录")
195		}
196		if o2, _ := e.Order(bid); o2.Status != StatusCanceled || o2.Filled != 2 {
197			t.Fatalf("重放不得再次改变订单: %+v", o2)
198		}
199		if e.Cash() != 980 || e.ReservedCash() != 0 || e.Position("A") != 2 {
200			t.Fatalf("重放不得改变资金与持仓: cash=%d reserved=%d pos=%d",
201				e.Cash(), e.ReservedCash(), e.Position("A"))
202		}
203	}
204	
205	// TestPendingQuoteConflictRejectedDataNeverReplacesWaitingQuote 在无订单、无限额
206	// 的最小构造下单独锁定报价语义：对等待中的同序号报价，改价或改时刻的冲突
207	// 请求都只是被拒绝，真正决定补齐链内容的始终是第一次等待的数据。
208	func TestPendingQuoteConflictRejectedDataNeverReplacesWaitingQuote(t *testing.T) {
209		e, _ := NewEngine(1000)
210		mustSetMax(t, e, "A", 100)
211		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 10, Price: 10}, 1)
212		recsBase := len(e.Records())
213	
214		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 30, Price: 20}, 0)
215	
216		// 两组冲突数据先后被拒。
217		for _, q := range []Quote{
218			{Seq: 3, Moment: 30, Price: 10}, // 仅价格不同
219			{Seq: 3, Moment: 99, Price: 20}, // 仅时刻不同
220		} {
221			if n, err := e.UpdateQuote("A", q); err == nil || n != 0 {
222				t.Fatalf("冲突报价 %+v 必须报错并返回 0: n=%d err=%v", q, n, err)
223			}
224		}
225	
226		// 最新报价仍停在 seq1，缺口保持，事件记录一条不多。
227		q, ok := e.CurrentQuote("A")
228		if !ok || q.Seq != 1 || q.Moment != 10 || q.Price != 10 {
229			t.Fatalf("冲突请求不得改变最新已生效报价: %+v ok=%v", q, ok)
230		}
231		if !e.HasGap("A") {
232			t.Fatal("冲突请求不得消除缺口")
233		}
234		if len(e.Records()) != recsBase {
235			t.Fatalf("等待重放与内容冲突都不得新增事件记录: 基础 %d，现有 %d",
236				recsBase, len(e.Records()))
237		}
238	
239		// 补齐 seq2：必须按最初等待的 (时刻30,价格20) 推进，而不是任一冲突数据。
240		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 20, Price: 10})
241		if err != nil || n != 2 {
242			t.Fatalf("补齐应使 seq2/seq3 依次生效: n=%d err=%v", n, err)
243		}
244		q, ok = e.CurrentQuote("A")
245		if !ok || q != (Quote{Seq: 3, Moment: 30, Price: 20}) {
246			t.Fatalf("补齐后必须保留最初等待的 seq3（时刻30,价格20）: %+v ok=%v", q, ok)
247		}
248		if e.HasGap("A") {
249			t.Fatal("补齐后缺口必须消失")
250		}
251	}
